    14→package com.google.auto.value;
    15→
    16→import java.lang.annotation.ElementType;
    17→import java.lang.annotation.Retention;
    18→import java.lang.annotation.RetentionPolicy;
    19→import java.lang.annotation.Target;
    20→
    21→@Retention(RetentionPolicy.SOURCE)
    22→@Target(ElementType.TYPE)
    23→public @interface AutoValue {
    24→
    25→  /**
    26→   * Specifies that AutoValue should generate an implementation of the annotated class or interface,
    27→   * to serve as a <i>builder</i> for the value-type class it is nested within. As a simple example,
    28→   * here is an alternative way to write the {@code Person} class mentioned in the {@link AutoValue}
    29→   * example: <pre>
    30→   *
    31→   *   &#64;AutoValue
    32→   *   abstract class Person {
    33→   *     static Builder builder() {
    34→   *       return new AutoValue_Person.Builder();
    35→   *     }
    36→   *
    37→   *     abstract String name();
    38→   *     abstract int id();
    39→   *
    40→   *     &#64;AutoValue.Builder
    41→   *     interface Builder {
    42→   *       Builder name(String x);
    43→   *       Builder id(int x);
    44→   *       Person build();
    45→   *     }
    46→   *   }</pre>
    47→   *
    48→   * @author Éamonn McManus
    49→   */
    50→  @Retention(RetentionPolicy.SOURCE)
    51→  @Target(ElementType.TYPE)
    52→  public @interface Builder {}
    53→}
